/* kerb cross-section: a raised, rounded bump (like real kerbs), [distance from the road edge, height] */
export const KERB_PROFILE = [[-0.03, 0.012], [0.07, 0.05], [0.22, 0.072], [0.7, 0.08], [1.18, 0.085], [1.32, 0.05], [1.4, 0.012]];
export function kerbHeight(d) { // d = metres beyond the road edge
  const P = KERB_PROFILE; if (d <= P[0][0] || d >= P[P.length - 1][0]) return 0;
  for (let k = 1; k < P.length; k++) if (d <= P[k][0]) { const [a, ha] = P[k - 1], [b, hb] = P[k]; return ha + (hb - ha) * (d - a) / (b - a); }
  return 0;
}
